color_swap_imposed.new:
    return min(node["infoset"], self.imposed_swap(node["infoset"]))

@staticmethod
def imposed_swap(s: str) -> str:
    return " ".join(t if "|start:" in t else color_swap(t) for t in s.split(" "))

def act_label(self, node: dict, label: str) -> str:
    """The imposed swap renames the actions of the image infoset to match its row."""
    if self.imposed_swap(node["infoset"]) < node["infoset"]:
        return color_swap(label)
    return label
